        col_modes.append(mode)

    # Count transitions to determine orientation
    row_trans = sum(1 for i in range(rows-1) if row_modes[i] != row_modes[i+1])
    col_trans = sum(1 for i in range(cols-1) if col_modes[i] != col_modes[i+1])

